def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the divider; when an incidental uniform line exists too,
    # prefer the line whose color appears least elsewhere in the grid.
    candidates = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            candidates.append(("row", r, grid[r][0]))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            candidates.append(("col", c, grid[0][c]))

    def outside_count(item):
        kind, pos, color = item
        return sum(v == color for r, row in enumerate(grid)
                   for c, v in enumerate(row)
                   if not (kind == "row" and r == pos)
                   and not (kind == "col" and c == pos))

    kind, pos, _ = min(candidates, key=outside_count)
    if kind == "row":
        a, b = grid[:pos], grid[pos + 1:]
        oh, ow = min(len(a), len(b)), w
        a, b = a[:oh], b[:oh]
    else:
        a = [row[:pos] for row in grid]
        b = [row[pos + 1:] for row in grid]
        oh, ow = h, min(len(a[0]), len(b[0]))
        a = [row[:ow] for row in a]
        b = [row[:ow] for row in b]

    def foreground(panel):
        counts = {}
        for row in panel:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        bg = max(counts, key=counts.get)
        return [[v != bg for v in row] for row in panel]

    fa, fb = foreground(a), foreground(b)
    return [[2 if fa[r][c] and fb[r][c] else 0
             for c in range(ow)] for r in range(oh)]
